insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_mt4_v1'
from (values
('117.322.c.1.A',3,'A senior designs a full warm-up for the company and runs it before every rehearsal of the spring musical. She is ___ preparation.','["Creating and leading", "Cancelling", "Sorting tickets for", "Dodging"]'::jsonb,0,'Level IV students lead company warm-ups.','original'),
('117.322.c.1.A',3,'Which warm-up best prepares a company for a rehearsal with both belting and jazz choreography?','["Only a lobby tour", "Breath and vocal exercises followed by dynamic stretching and a movement sequence", "Silence and sitting", "Only a costume check"]'::jsonb,1,'Warm-ups must match the work.','original'),
('117.322.c.1.B',3,'A senior student director plans how a crowd of twenty moves from the town square to a church in under a minute. She is ___ stage movement.','["Selling", "Erasing", "Arranging", "Hiding"]'::jsonb,2,'Arranging means planning movement on stage.','original'),
('117.322.c.1.B',3,'Which choice makes large-group stage movement clear for an audience?','["Random wandering", "Everyone running at once", "Everyone facing upstage", "Planned paths, levels and focus points for each group"]'::jsonb,3,'Planned patterns guide the eye.','original'),
('117.322.c.1.C',3,'A senior student creates a number combining ballroom, tap and jazz sections for a dream sequence. She is ___.','["Choreographing", "Surveying", "Auditing", "Accounting"]'::jsonb,0,'Choreography designs dance movement.','original'),
('117.322.c.1.C',3,'Which feature suits a choreographed Broadway-style finale?','["No planned formation", "A strong opening picture, building patterns, and a big final pose", "Slow walking only", "One dancer alone for ten minutes"]'::jsonb,1,'Finales build to a peak.','original'),
('117.322.c.1.D',3,'A student actor practices crisp consonants, open vowels and varied pacing in a long speech from a script. She is developing ___.','["Fly system skills", "Light plotting", "Voice and diction for spoken dialogue", "Prop making"]'::jsonb,2,'Diction makes dialogue clear.','original'),
('117.322.c.1.D',3,'Which technique helps an actor be understood in the back row?','["Whispering", "Speaking only to the floor", "Swallowing words", "Supported breath, clear articulation and projection"]'::jsonb,3,'Projection reaches the audience.','original'),
('117.322.c.1.E',3,'A singer works on pitch accuracy, breath control and blend in both solo and ensemble pieces. She is developing ___.','["Singing technique for solo and ensemble work", "Poster design", "Ticketing", "Set building"]'::jsonb,0,'Technique serves both settings.','original'),
('117.322.c.1.E',3,'In an ensemble number, how should a singer treat her own volume?','["Ignore the conductor", "Blend with the group while keeping her part accurate", "Stop singing", "Sing as loudly as possible"]'::jsonb,1,'Blend is key.','original'),
('117.322.c.1.F',3,'A senior leads a mock audition for younger students, showing how to slate, present sheet music and perform a monologue. She is modeling ___.','["Strike procedures", "Press interviews", "Professional audition technique", "Marketing"]'::jsonb,2,'Modeling demonstrates the standard.','original'),
('117.322.c.1.F',3,'After an audition, what is the professional way to leave the room?','["Argue with the casting team", "Ask for the role aloud", "Sing again uninvited", "Thank the panel and exit calmly"]'::jsonb,3,'Courtesy is part of professionalism.','original'),
('117.322.c.1.G',3,'A senior portrays a role who sings, dances and delivers dialogue, keeping a rich inner life for the character throughout. She is performing a ___ character.','["Multi-dimensional", "Missing", "Flat", "Ignored"]'::jsonb,0,'Characters have layers.','original'),
('117.322.c.1.G',3,'What makes a character multi-dimensional in a musical?','["Only a bright costume", "Depth in thoughts, feelings, habits and relationships shown in song, dance and speech", "Only a loud voice", "Only a pose"]'::jsonb,1,'Depth appears in all modes.','original'),
('117.322.c.1.H',3,'A senior student works with the composer''s score, the lighting designer''s cues and the choreographer''s patterns to align the finale. She is collaborating ___.','["Against everyone", "Without a plan", "With all artistic partners", "Alone"]'::jsonb,2,'Collaboration aligns all elements.','original'),
('117.322.c.1.H',3,'If the lighting designer and the choreographer disagree on a cue, a student director should ___.','["Pick sides at random", "Ignore both", "Cancel the show", "Facilitate a discussion to solve it for the good of the production"]'::jsonb,3,'Directors mediate.','original'),
('117.322.c.2.A',3,'A senior demonstrates safe landings, warm-ups and vocal rest, and teaches them to the cast. She is ___ safety.','["Modeling", "Breaking", "Avoiding", "Ignoring"]'::jsonb,0,'Modeling shows correct habits.','original'),
('117.322.c.2.A',3,'Which habit models safe theatrical movement during a fight or stunt scene?','["Skip rehearsal", "Rehearse slowly, mark contact points and use trained supervision", "Improvise at full speed", "Use real weapons"]'::jsonb,1,'Safe staging prevents injury.','original'),
('117.322.c.2.B',3,'A senior explains in a presentation why creative risks by an individual and an ensemble made the show better. She is ___ creativity.','["Banning", "Hiding", "Defending", "Rejecting"]'::jsonb,2,'Defend means to support with reasons.','original'),
('117.322.c.2.B',3,'Which is a strong argument for creativity in a musical?','["Choices don''t matter", "Copying is always safest", "Creativity wastes time", "Original choices make characters and numbers fresh and memorable"]'::jsonb,3,'Creativity enriches performance.','original'),
('117.322.c.2.C',3,'A student compares a comic operetta role with a gritty realistic musical role in the way each is sung, moved and spoken. She is analyzing ___.','["Characterization in different styles", "Seating charts", "Ticket prices", "Scene shop budgets"]'::jsonb,0,'Style shapes characterization.','original'),
('117.322.c.2.C',3,'How does the style of a show change an actor''s physical choices?','["All styles use identical movement", "Heightened styles use bigger, more stylized movement than realistic ones", "Actors never move", "Style never matters"]'::jsonb,1,'Choices follow style.','original'),
('117.322.c.2.D',3,'A senior teaches her peers how to place the voice forward, support the sound and shape vowels. She is modeling ___.','["Costume rules", "Programs", "Proper voice usage", "Bad habits"]'::jsonb,2,'Modeling shows correct production.','original'),
('117.322.c.2.D',3,'Which sign shows a singer is using good vocal placement?','["Straining the neck", "Tight jaw", "Shouting", "A clear, resonant tone without forced strain"]'::jsonb,3,'Healthy tone indicates correct placement.','original'),
('117.322.c.2.E',3,'A student reads a solo as a monologue and finds the objective, obstacle and change in each stanza. She is ___ lyrics.','["Analyzing", "Burying", "Selling", "Skipping"]'::jsonb,0,'Lyric analysis reveals dramatic action.','original'),
('117.322.c.2.E',3,'Reading an ensemble number as a scene helps performers decide ___.','["How to sell tickets", "How each voice reacts to and influences the others", "Which light to buy", "The parking layout"]'::jsonb,1,'Ensemble reading reveals relationships.','original'),
('117.322.c.2.F',3,'Over several weeks, an actor builds a character''s habits, voice and dance style and keeps them steady through every performance. She is ___ the character.','["Shrinking", "Cutting", "Creating and sustaining", "Forgetting"]'::jsonb,2,'Consistency makes the role believable.','original'),
('117.322.c.2.F',3,'What can help an actor keep a character consistent in a long run?','["Ignoring notes", "Never rehearsing again", "Changing the role nightly", "Notes on the character''s choices and a regular warm-up"]'::jsonb,3,'Notes and routines preserve consistency.','original'),
('117.322.c.2.G',3,'A senior collaborates with two classmates to write lyrics and dialogue and choreograph an original scene. They are ___ material.','["Producing", "Selling", "Cancelling", "Erasing"]'::jsonb,0,'Producing includes writing and staging.','original'),
('117.322.c.2.G',3,'Which helps a group write an original musical scene together?','["Ignoring deadlines", "Sharing ideas, agreeing on a goal and assigning tasks", "Working without a goal", "Writing alone and refusing input"]'::jsonb,1,'Collaboration needs shared direction.','original'),
('117.322.c.3.A',3,'A senior teaches the crew how to run a fly rail safely, check cables and clear the stage before a move. She is ___ safe technical practice.','["Ending", "Ignoring", "Modeling", "Mocking"]'::jsonb,2,'Modeling demonstrates correct procedure.','original'),
('117.322.c.3.A',3,'Why should a lighting operator follow written cues exactly?','["To shorten the show", "To confuse actors", "To save electricity only", "To keep the scene safe, clear and timed with the music"]'::jsonb,3,'Cues coordinate the show.','original'),
('117.322.c.3.B',3,'A senior writes a plan that includes research, a rehearsal calendar, technical designs, blocking and choreography notes. She is ___ a production plan.','["Creating", "Tearing down", "Cancelling", "Selling"]'::jsonb,0,'Plans organize every part.','original'),
('117.322.c.3.B',3,'Which part of a production plan helps the technical crew most?','["A bus schedule", "A cue sheet listing lights, sound and scenery changes", "A lobby decoration list", "A parking diagram"]'::jsonb,1,'Cue sheets guide the crew.','original'),
('117.322.c.3.C',3,'A senior student director holds auditions, picks a cast, schedules rehearsals and gives notes. She is ___ a production.','["Cancelling", "Erasing", "Casting and directing", "Avoiding"]'::jsonb,2,'Directors cast and guide.','original'),
('117.322.c.3.C',3,'Which factor should a director weigh when casting a lead role in a musical?','["Who arrived first only", "Who sits nearest", "Whose name is longest", "Vocal range, acting ability, dance skill and fit for the character"]'::jsonb,3,'Casting weighs several skills.','original'),
('117.322.c.4.A',3,'A student spends several weeks researching how vaudeville, operetta, jazz and rock changed musicals and writes a report. She is conducting ___.','["A concentrated study", "A coin flip", "A quick glance", "A rumor"]'::jsonb,0,'Concentrated studies are focused research.','original'),
('117.322.c.4.A',3,'Which source is most useful for a concentrated study of musical theatre history?','["Random posts", "Books, recordings and interviews from reliable authors", "Guesses", "Rumors"]'::jsonb,1,'Reliable sources support research.','original'),
('117.322.c.4.B',3,'A student presents evidence that musical theatre combined many American traditions into an original art form. She is ___ the claim.','["Burying", "Dodging", "Justifying", "Deleting"]'::jsonb,2,'Justify means to give reasons.','original'),
('117.322.c.4.B',3,'Which fact supports the claim that musical theatre is an original American art form?','["It is only a copy of opera", "It was invented in ancient Greece", "It has no relation to America", "It merged jazz, popular song, dance and drama into a new type of show"]'::jsonb,3,'Blending traditions made a new form.','original'),
('117.322.c.4.C',3,'A student stages a scene that shows the worries and hopes of a particular era and place through song and costume. She is ___ musical theatre as a reflection of life.','["Depicting", "Hiding", "Burying", "Ignoring"]'::jsonb,0,'Depict means to show.','original'),
('117.322.c.4.C',3,'Which choice would help depict a particular culture in a musical?','["A random mix of unrelated items", "Music, dance and clothing from that culture used respectfully", "Mockery", "No research"]'::jsonb,1,'Authentic details need respect.','original'),
('117.322.c.4.D',3,'A student argues that film musicals and televised musicals have changed how stage musicals are designed and staged. She is ___ the influence.','["Denying", "Ignoring", "Defending", "Burying"]'::jsonb,2,'Defend means to argue support.','original'),
('117.322.c.4.D',3,'How has film influenced stage musicals?','["Film bans live actors", "Film has no effect", "Stage shows stop using music", "Stage shows adopt cinematic pacing, projections and quick scene shifts"]'::jsonb,3,'Film changed stage techniques.','original'),
('117.322.c.5.A',3,'A senior teaches classmates how to behave at a symphony, a community musical and an outdoor show. She is ___ audience behavior.','["Practicing and evaluating", "Ignoring", "Breaking", "Hiding"]'::jsonb,0,'Behavior varies by venue.','original'),
('117.322.c.5.A',3,'At an outdoor musical festival, what is considerate audience behavior?','["Block views", "Keep sightlines clear and respond to the performance without disrupting others", "Shout over the performers", "Leave trash"]'::jsonb,1,'Courtesy applies everywhere.','original'),
('117.322.c.5.B',3,'A student writes an essay arguing that musical theatre combines story, music and movement to express ideas. She is ___ it as an art form.','["Rejecting", "Skipping", "Defending", "Banning"]'::jsonb,2,'Defend means to support.','original'),
('117.322.c.5.B',3,'Which sentence best defends musical theatre as a creative art?','["It makes money only", "It is easy", "It is only for children", "It tells stories that move audiences through song, dance and design"]'::jsonb,3,'Creativity and expression define art.','original'),
('117.322.c.5.C',3,'A student compares how a musical, an opera and a music video each combine sound, story and image. She is comparing the nature of ___.','["Elements across musical media", "Tax forms", "Weather patterns", "School bus routes"]'::jsonb,0,'Compare means to find similarities and differences.','original'),
('117.322.c.5.C',3,'What is one difference between musical theatre and opera?','["Opera has no singing", "Musicals often mix spoken dialogue with song more freely than most operas", "Musicals have no orchestras", "Opera never tells stories"]'::jsonb,1,'Spoken dialogue is more typical in musicals.','original'),
('117.322.c.5.D',3,'A senior gives a classmate feedback listing a strength in phrasing and one change to improve the transition. She is ___ the performance.','["Dismissing", "Selling", "Appraising", "Ignoring"]'::jsonb,2,'Appraise means to assess.','original'),
('117.322.c.5.D',3,'What makes peer criticism constructive?','["It lists only faults", "It is rude", "It is vague", "It names specifics, stays respectful and suggests a change"]'::jsonb,3,'Specific, kind feedback helps.','original'),
('117.322.c.5.E',3,'A critic''s review uses terms like blocking, tempo, harmony and motif. This shows ___.','["Precise musical theatre vocabulary", "Slang only", "Poor language", "Silence"]'::jsonb,0,'Vocabulary adds precision.','original'),
('117.322.c.5.E',3,'Which statement is a precise evaluation of a musical?','["It was okay", "The orchestration lifted the second-act ballad and the dance matched the tempo", "Cool show", "I liked it"]'::jsonb,1,'Specific terms add clarity.','original'),
('117.322.c.5.F',3,'A student interns with a community theatre''s stage manager to experience the work firsthand. She is ___ with a career opportunity.','["Retiring", "Banning", "Experimenting", "Avoiding"]'::jsonb,2,'Internships let students try careers.','original'),
('117.322.c.5.F',3,'Which is a job that may exist in musical film or other musical media?','["Pilot", "Welder", "Surveyor", "Orchestrator"]'::jsonb,3,'Orchestrators arrange music.','original'),
('117.322.c.5.G',3,'A senior says that teamwork, leadership and public speaking from her musical theatre years will help in college and any career. She is ___ theatre skills to the future.','["Relating", "Hiding", "Dropping", "Ending"]'::jsonb,0,'Skills transfer.','original'),
('117.322.c.5.G',3,'How can acting and singing experience help someone in a business presentation?','["It removes planning", "It builds confidence, voice control and audience awareness", "It prevents speaking", "It avoids audiences"]'::jsonb,1,'Performance skills transfer.','original'),
('117.322.c.5.H',3,'A senior assembles a digital portfolio with performance clips, program notes, a résumé and short reflections. She is ___ information with technology.','["Deleting", "Hiding", "Documenting and presenting", "Skipping"]'::jsonb,2,'Portfolios organize evidence of growth.','original'),
('117.322.c.5.H',3,'A portfolio for college auditions should ___.','["Hold only one clip", "Be unlabeled", "Skip dates", "Be clearly organized and show a range of work"]'::jsonb,3,'Clarity and range impress.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Fine Arts' and d.language = 'en'
on conflict (fingerprint) do nothing;
